body {
    font-family: Georgia, serif;
    margin: 0;
    padding: 0;
    color: #000;
}

/* Hide elements that shouldn't be printed */
.no-print {
    display: none !important;
}

/* Adjust margins and paddings for print */


/* Adjust header and paragraph styles for print */
h1 {
    font-size: 24pt;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

p {
    font-size: 12px;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

/* Page break styles */
@page {
    size: auto;
    margin: 1in;
}

@media print {

    /* Page breaks */
    .content {
        page-break-after: always;
    }
}

body {
    font-family: Arial, sans-serif;
    line-height: 1.6;
}

.content {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.no-print {
    display: none;
}

.contentHeader {
    display: flex;
    justify-content: center;

}

.contentHeader p {
    text-transform: uppercase;
    text-align: center;
}

.SettingSections {
    display: flex;
    width: 100%;
}

.SettingFirstSection {
    width: 50%;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.SettingFirstSectionSec {
    width: 130px;

}

.SettingFirstSectionFle {
    display: flex;
    gap: 10px;
}

.UpperCase {
    text-transform: uppercase;
}

.SettingFirstSectionFlegap {
    display: flex;
    flex-direction: column;
}

.extraGap {
    display: flex;
    flex-direction: column;
    gap: 80px;
}

.SettingsecondSecSmallgap {
    display: flex;
    flex-direction: column;
    gap: 50px;
}

.contentTable table {
    width: 100%;
    font-size: 12px;
}

.borderBottom {
    border-bottom: 1px solid black;
}

.borderTop {
    border-top: 1px solid black;
}

.contentTable table {
    border: 1px solid black;
}

.contentTable th {
    border-bottom: 1px solid black;
    text-align: start;
}

.contentNotes {
    margin-top: 30px;
}

.contentNotesFont {
    font-family: auto;
}

.contentNotesPadding {
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.contentNotesPadding p {
    font-size: 12px;
}

.underline {
    text-decoration: underline;
}

h5 {
    margin-block-end: 0px;
    margin-block-start: 0px;
    font-size: 15px;
}

.fontSizeP {
    font-size: 10px;
}
